import {languageFor} from './languages.mjs';
import {catalog,entriesFor} from './catalog.mjs';
export const WELCOME_KEY='education-facilitation-guide:welcome';
export const welcomeStages=[['18m','18–23 meses','Un turno contigo'],['2y','24–35 meses','Imitar juntos'],['3y','3–5 años','Mirar y probar'],['5y','6–8 años','Explorar con ayuda'],['7y','9–12 años','Comparar ideas'],['12y','13–18 años','Preguntar con razones']];
export function decodeWelcome(raw){
 if(raw===null)return {ok:true,value:null};
 try{if(typeof raw!=='string'||raw.length>160)throw Error();const p=JSON.parse(raw);if(!p||Object.keys(p).sort().join(',')!=='role,stage,version'||p.version!==1||!['adult','student'].includes(p.role)||!welcomeStages.some(s=>s[0]===p.stage)||(p.role==='student'&&!['7y','12y'].includes(p.stage)))throw Error();return {ok:true,value:p};}catch{return {ok:false,value:null};}
}
const art=(kind='path')=>`<svg class="welcome-art" viewBox="0 0 320 180" aria-hidden="true"><rect x="4" y="4" width="312" height="172" rx="38" fill="#e9eedf"/><path d="M35 140 Q100 40 160 120 T290 55" fill="none" stroke="#9caa85" stroke-width="5" stroke-dasharray="8 10"/><circle cx="78" cy="104" r="30" fill="#215747"/><path d="M78 122 V85 M78 104 Q56 104 60 85 Q78 85 78 104 M78 96 Q97 96 95 78 Q78 79 78 96" fill="none" stroke="#fffdf5" stroke-width="3"/>${kind==='ball'?'<circle cx="205" cy="120" r="29" fill="#b45e40"/><path d="M180 108 Q205 135 230 108" fill="none" stroke="#fffdf5" stroke-width="3"/>':'<rect x="180" y="56" width="64" height="64" rx="14" fill="#e4bc69"/><path d="M195 90 L207 101 L229 76" fill="none" stroke="#354b36" stroke-width="5"/>'}<circle cx="264" cy="34" r="12" fill="#e4bc69"/></svg>`;
const goalArt=a=>`<svg class="welcome-goal-art" viewBox="0 0 120 70" aria-hidden="true"><rect width="120" height="70" rx="18" fill="#e9eedf"/>${a.type==='guide'?'<circle cx="60" cy="36" r="23" fill="#b45e40"/><path d="M38 31 Q60 51 82 31" fill="none" stroke="#fffdf5" stroke-width="3"/>':a.area==='Idiomas'||a.area==='Lenguaje'?'<path d="M24 15 H96 V49 H58 L42 60 V49 H24 Z" fill="#215747"/><path d="M38 28 H81 M38 38 H68" stroke="#fffdf5" stroke-width="4"/>':a.area==='Pensamiento crítico'||a.area==='Ciencia'?'<circle cx="54" cy="30" r="17" fill="#e4bc69" stroke="#215747" stroke-width="5"/><path d="M67 44 L87 61 M44 30 H64 M54 20 V40" stroke="#215747" stroke-width="5"/>':'<rect x="23" y="33" width="24" height="24" rx="5" fill="#215747"/><circle cx="77" cy="23" r="15" fill="#b45e40"/><path d="M61 57 L77 35 L94 57 Z" fill="#b58b35"/>'}</svg>`;
export function mountWelcome(root,{storage,getResume,openActivity,onHome}){
 let baseline=null,pref=null,message='',step=0,role='adult',band=null,demo=false;
 try{baseline=storage?.getItem(WELCOME_KEY)??null;const decoded=decodeWelcome(baseline);pref=decoded.value;if(!decoded.ok)message='No pudimos leer este inicio. Lo conservamos sin sustituirlo.';}catch{message='Puedes explorar sin guardar este inicio.';}
 if(pref){role=pref.role;band=pref.stage;}
 const library=document.querySelector('#all-proposals'),stageSection=document.querySelector('#etapas'),anchor=document.createComment('stage home');stageSection.before(anchor);
 const back=document.querySelector('#back-home');
 const setHome=()=>{document.body.classList.remove('guided-session','garden-focus');anchor.after(stageSection);back.hidden=true;onHome();document.body.classList.remove('garden-focus');step=0;draw();root.querySelector('h1')?.focus();};
 back.addEventListener('click',setHome);
 const launch=key=>{document.body.classList.add('guided-session');back.after(stageSection);back.hidden=false;openActivity(key);};
 const mutate=value=>{
  try{if(!storage)throw Error();const now=storage.getItem(WELCOME_KEY);if(now!==baseline||!decodeWelcome(now).ok){message='Este inicio cambió en otra pestaña o no se puede leer. Recarga antes de guardarlo; tus juegos se conservan.';return;}
   if(value===null)storage.removeItem(WELCOME_KEY);else storage.setItem(WELCOME_KEY,JSON.stringify(value));
   const expected=value===null?null:JSON.stringify(value);if(storage.getItem(WELCOME_KEY)!==expected)throw Error();baseline=expected;pref=value;message=value?'Inicio recordado en este navegador. No cambia tus juegos.':'Preferencias del inicio borradas. Tus juegos y Luma se conservan.';
  }catch{message='No se pudo guardar este inicio. Puedes seguir en esta sesión; tus juegos no se borran.';}
 };
 const bind=(id,fn)=>root.querySelector('#'+id)?.addEventListener('click',fn);
 const render=()=>{draw();root.querySelector('[tabindex="-1"]')?.focus();};
 function draw(){
  const resume=getResume(),info=welcomeStages.find(s=>s[0]===band),young=['18m','2y'].includes(band),adult=!['7y','12y'].includes(band)||role==='adult';
  let content='';
  if(step===0)content=`<div class="welcome-lead"><div><p class="eyebrow">A TU RITMO · CON ESPACIO PARA PARAR</p><h1 tabindex="-1">Un pequeño paso.<br><em>Juntos, o con tu propia voz.</em></h1><p>Te ayudamos a elegir una propuesta para hoy.</p><div class="controls">${resume?`<button type="button" class="action primary" id="welcome-continue">Continuar · ${resume.unit}</button>`:''}<button type="button" class="action ${resume?'secondary':'primary'}" id="welcome-begin">${resume?'Elegir otra actividad':pref?'Elegir una actividad':'Encontrar por dónde empezar'}</button></div>${resume?`<p class="quiet">${welcomeStages.find(s=>s[0]===resume.stage)?.[1]||''} · ${resume.phase==='paused'?'En pausa':'En curso'}</p>`:''}</div>${art()}</div>`;
  if(step===1)content=`<p class="eyebrow">1 DE 3 · COMPAÑÍA</p><h1 tabindex="-1">¿Cómo vamos a explorar?</h1><div class="welcome-choices"><button type="button" class="welcome-choice" data-role="adult">${art('ball')}<strong>Un adulto con un niño o estudiante</strong><span>Yo acompaño, leo y ajusto la ayuda.</span></button><button type="button" class="welcome-choice" data-role="student">${art()}<strong>Soy estudiante</strong><span>Puedo leer por mi cuenta y pedir apoyo.</span></button></div>`;
  if(step===2)content=`<p class="eyebrow">2 DE 3 · UN PUNTO DE PARTIDA</p><h1 tabindex="-1">Elige una franja orientativa.</h1><p>No necesitamos tu fecha de nacimiento. Puedes cambiar después.</p><div class="welcome-bands">${welcomeStages.map(([id,label,note],i)=>`<button type="button" class="welcome-choice" data-band="${id}"><span class="welcome-number" aria-hidden="true">${['○','◒','△','◇','⌁','✳'][i]}</span><strong>${label}</strong><span>${note}</span></button>`).join('')}</div>`;
  if(step===3){
   const entries=entriesFor(band).sort((a,b)=>Number(a.id==='words')-Number(b.id==='words')),primary=entries.slice(0,3),extra=entries.slice(3);
   const card=a=>`<button type="button" class="welcome-choice" data-welcome-route="${a.key}">${goalArt(a)}<span>${a.area}</span><strong>${languageFor(a.id)?languageFor(a.id).name+' · ':''}${a.unit}</strong>${a.age?`<span>${a.age}</span>`:''}<span>${a.type==='guide'?'Ver la guía del adulto':'Abrir esta actividad'} · disponible</span></button>`;
   content=`<p class="eyebrow">3 DE 3 · ${info[1]} · ${adult?'CON ADULTO':'CON APOYO SI LO NECESITAS'}</p><h1 tabindex="-1">${young?'Tú acompañas. La pantalla espera.':'¿Qué te apetece probar hoy?'}</h1>${young?`<div class="welcome-demo">${art('ball')}<div><p>Solo para quien acompaña: mira un gesto y llévalo al juego real.</p><button type="button" class="action secondary" id="welcome-demo">${demo?'Ocultar el ejemplo':'Ver un ejemplo breve'}</button>${demo?`<p role="status">${band==='18m'?'Haz rodar suavemente una pelota grande y blanda. Espera: puede mirar, tocar o elegir otra cosa.':'Saluda a un muñeco y muéstrale cómo descansar. Invita a imitar o cambiar la historia.'}</p><p>Espacio despejado, materiales adecuados sin piezas pequeñas y supervisión directa. Aparta la pantalla para jugar.</p>`:''}</div></div>`:`<p>${band==='3y'?'Un adulto lee; pueden señalar, probar juntos y parar.':'Elige una idea. No hay un orden obligatorio ni un nivel que superar.'}</p><ol class="welcome-map" aria-label="Tu próximo paso"><li>Elige</li><li>Prueba con ayuda</li><li>Llévalo fuera de pantalla</li></ol>`}<div class="welcome-choices">${primary.map(card).join('')}</div>${extra.length?`<details class="welcome-more"><summary>Más propuestas de esta franja (${extra.length})</summary><div class="welcome-choices">${extra.map(card).join('')}</div></details>`:''}<details class="welcome-family"><summary>${young?'Antes de apartar la pantalla':'Una idea para acompañar'}</summary><p>${young?'No hay juego autónomo en pantalla ni pasos que el pequeño deba completar. Sigue su iniciativa; puedes parar ahora.':'Ofrece una pista y espera. Se puede señalar, pedir ayuda, cambiar de propuesta o descansar. No hace falta acertar para que la conversación tenga valor.'}</p><p>Estas franjas y sugerencias organizan la interfaz. No evalúan capacidades ni constituyen un currículo o una eficacia educativa validada.</p></details><div class="controls"><button type="button" class="action secondary" id="welcome-remember">Recordar este inicio</button><button type="button" class="action secondary" id="welcome-band">Cambiar franja</button></div><p class="quiet">Recordar guarda solo franja y tipo de acompañamiento en este navegador compartido.</p>`;
  }
  root.innerHTML=content+`<div class="welcome-tools">${step>0?'<button type="button" class="action secondary" id="welcome-back">Atrás</button>':''}<button type="button" class="action secondary" id="welcome-skip">${step?'Omitir guía · ver todas las áreas':'Explorar todas las áreas'}</button>${pref?'<button type="button" class="action secondary" id="welcome-reset">Olvidar preferencias del inicio</button>':''}</div><p id="welcome-status" role="status" aria-live="polite">${message}</p>`;
  bind('welcome-begin',()=>{step=pref?3:1;render();});bind('welcome-continue',()=>{const candidate=getResume();if(candidate)launch(candidate.key);else render();});
  root.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;band=null;step=2;demo=false;message='';render();});
  root.querySelectorAll('[data-band]').forEach(b=>b.onclick=()=>{band=b.dataset.band;if(!['7y','12y'].includes(band))role='adult';step=3;demo=false;message=pref&&(pref.stage!==band||pref.role!==role)?'Cambio solo en esta sesión. Pulsa «Recordar este inicio» si quieres conservarlo.':'';render();});
  root.querySelectorAll('[data-welcome-route]').forEach(b=>b.onclick=()=>launch(b.dataset.welcomeRoute));
  bind('welcome-demo',()=>{demo=!demo;draw();root.querySelector('#welcome-demo').focus();});
  bind('welcome-back',()=>{step=Math.max(0,step-1);demo=false;render();});bind('welcome-band',()=>{step=2;demo=false;render();});
  bind('welcome-remember',()=>{mutate({version:1,role,stage:band});render();});
  bind('welcome-reset',()=>{mutate(null);if(pref===null){band=null;role='adult';step=0;}render();});
  bind('welcome-skip',()=>{library.open=true;library.querySelector('summary').focus();library.scrollIntoView?.({block:'start'});});
 }
 const showCatalog=()=>{document.body.classList.remove('guided-session','garden-focus');anchor.after(stageSection);back.hidden=true;library.open=true;draw();};
 document.addEventListener('click',event=>{const trigger=event.target.closest('#garden-library,#paused-catalog,#finished-catalog');if(document.body.classList.contains('guided-session')&&trigger){event.preventDefault();showCatalog();const target=trigger.id==='finished-catalog'?document.querySelector('#stage-buttons [aria-pressed="true"]'):document.querySelector('#stage-title');target?.focus();stageSection.scrollIntoView?.({block:'start'});}});
 document.querySelectorAll('a[href="#principios"],.explore-nav a').forEach(a=>a.addEventListener('click',()=>{if(document.body.classList.contains('guided-session'))showCatalog();library.open=true;}));
 document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();setHome();});
 draw();
 return {refresh:()=>{if(step===0&&!document.body.classList.contains('guided-session'))draw();}};
}
